\section{Introduction}

\subsection{Setting}

A \emph{graded $G$-set} is a family $Y=(Y_n)_{n\ge0}$ of sets together with, for each $n$, a group $G_n$ acting on $Y_n$. The archetype is $Y_n=\{1,\dots,n\}$ with $G_n=S_n$, but the definition deliberately allows the group to vary with the grade, so that families such as $Y_n=\mathbb{F}_q^{\,n}$ with $G_n=\mathrm{GL}_n(\mathbb{F}_q)$ are covered.

Fix $r\ge0$. The \emph{$r$-tuple object} of a $G$-set $Y$ is
\[
  \Inj(r,Y)=\bigl\{\,f:\{1,\dots,r\}\hookrightarrow Y\,\bigr\},
\]
the set of injective maps from an $r$-element index set into $Y$, with $G$ acting pointwise by $(g\cdot f)(i)=g\cdot f(i)$; this is well defined because group elements act by bijections and so preserve injectivity. Write
\[
  t_r(Y)=\#\bigl(\Inj(r,Y)/G\bigr).
\]

\begin{definition}[$r$-transitivity]
A $G$-set $Y$ is \emph{$r$-transitive} if $\Inj(r,Y)\ne\emptyset$ and $G$ acts transitively on $\Inj(r,Y)$.
\end{definition}

\begin{definition}[Hilbert series]
The \emph{transitivity Hilbert series} of a graded $G$-set $Y$ at level $r$ is
\[
  H_r(q)=\sum_{n\ge0}t_r(Y_n)\,q^n\ \in\ \QQ[[q]].
\]
\end{definition}

We work throughout in the ring $\QQ[[q]]$ of formal power series; convergence never arises. The statement ``$H$ is rational with denominator dividing $(1-q)^k$'' is formalised as
\begin{equation}\label{eq:star}
  \exists\,P\in\QQ[q]:\qquad (1-q)^k H(q)=P(q).
\end{equation}
This is no weakening: $1-q$ has nonzero constant term and is therefore a unit of $\QQ[[q]]$, with inverse $1+q+q^2+\cdots$, so \eqref{eq:star} is equivalent to the honest quotient identity $H=P\cdot\bigl((1-q)^k\bigr)^{-1}$.

\subsection{The results}

\begin{theorem}[Rationality under eventual transitivity]\label{thm:A}
Let $Y$ be a graded $G$-set and suppose there is $N$ with $Y_n$ $r$-transitive for all $n\ge N$. Then there is $P\in\QQ[q]$ with
\[
  (1-q)\,H_r(q)=P(q).
\]
In particular $H_r$ is a rational function whose denominator divides $(1-q)^{r+1}$.
\end{theorem}

\begin{theorem}[Residue]\label{thm:B}
Under the hypotheses of Theorem~\ref{thm:A}, $P(1)=1$; equivalently the pole of $H_r$ at $q=1$ is simple with residue $-1$.
\end{theorem}

\begin{theorem}[Exact form]\label{thm:C}
If moreover $Y_n$ contains no injective $r$-tuple for every $n<N$, then $H_r(q)=q^N/(1-q)$.
\end{theorem}

\begin{theorem}[Sharpness of $r+1$]\label{thm:D}
For $Y_n=\{1,\dots,n\}$ with the trivial group acting in every grade,
\[
  t_r(Y_n)=n^{\underline r}=r!\binom{n}{r},\qquad (1-q)^{r+1}H_r(q)=r!\,q^r,
\]
and there is \emph{no} polynomial $P$ with $(1-q)^rH_r(q)=P(q)$. Hence the exponent $r+1$ cannot be lowered without a transitivity hypothesis.
\end{theorem}

\begin{theorem}[Classification]\label{thm:E}
For $a:\NN\to\QQ$ and $k\ge0$ the following are equivalent: (1) $(1-q)^k\sum_na_nq^n$ is a polynomial; (2) $\Delta^ka$ vanishes for all large $n$, where $(\Delta a)(n)=a(n+1)-a(n)$; (3) there are $N$ and $d_0,\dots,d_{k-1}\in\QQ$ with $a(n)=\sum_{j<k}d_j\binom{n-N}{j}$ for $n\ge N$; (4) with $k=r+1$: $a$ agrees for all large $n$ with a polynomial of degree at most $r$.
\end{theorem}

\begin{theorem}[Burnside route]\label{thm:F}
Let a fixed finite group $G$ act on every grade $Y_n$ of a graded set with all $Y_n$ finite. If for each $g\in G$ the number of injective $r$-tuples of $Y_n$ fixed by $g$ agrees for all large $n$ with a polynomial in $n$ of degree at most $r$, then $(1-q)^{r+1}H_r(q)$ is a polynomial, with no transitivity assumption whatsoever.
\end{theorem}

\begin{theorem}[Structure and profile]\label{thm:G}
The set of $f\in\QQ[[q]]$ with $(1-q)^kf$ polynomial for some $k$ is a subring $R_1\subseteq\QQ[[q]]$ containing $\QQ[q]$. Hilbert series of eventually $r$-transitive graded $G$-sets lie in $R_1$, so their sums and Cauchy products remain rational with poles only at $q=1$ (order at most $2$ for a product of two). Moreover $r$-transitivity is downward closed, so eventual $r$-transitivity makes every $H_s$ with $s\le r$ rational with a simple pole at $q=1$ and numerator satisfying $P_s(1)=1$.
\end{theorem}

\subsection{The picture}

Theorems~\ref{thm:A} and \ref{thm:D} concern \emph{the same underlying graded set} $Y_n=\{1,\dots,n\}$ and are best read side by side.

\begin{center}
\begin{tabular}{lccc}
\toprule
Group acting & $t_r(Y_n)$ & $H_r(q)$ & pole order at $q=1$\\
\midrule
$S_n$ (full symmetric) & $[\,n\ge r\,]$ & $q^r/(1-q)$ & $1$\\
trivial group & $r!\binom{n}{r}$ & $r!\,q^r/(1-q)^{r+1}$ & $r+1$\\
\bottomrule
\end{tabular}
\end{center}

The pole order measures the amount of symmetry in the grades, not their size: transitivity collapses the denominator.

\section{The finite difference engine}

\begin{definition}
For $a:\NN\to\QQ$ the \emph{forward difference} is $(\Delta a)(n)=a(n+1)-a(n)$. The sequence is \emph{eventually zero} if $a(n)=0$ for all $n\ge N$, some $N$. Its \emph{generating series} is $\operatorname{gen}(a)=\sum_na(n)X^n$.
\end{definition}

\begin{lemma}[Eventually zero $=$ polynomial]\label{lem:evz}
$\operatorname{gen}(a)$ is a polynomial iff $a$ is eventually zero.
\end{lemma}

\begin{proof}
If $a(n)=0$ for $n\ge N$ then $\operatorname{gen}(a)=\sum_{i<N}a(i)X^i$. Conversely $a(n)$ is the $n$-th coefficient of the polynomial, which vanishes above its degree.
\end{proof}

\begin{lemma}[Key identity]\label{lem:key}
For every $a$,
\[
  (1-X)\operatorname{gen}(a)=X\operatorname{gen}(\Delta a)+a(0).
\]
\end{lemma}

\begin{proof}
Compare coefficients: in degree $0$ both sides give $a(0)$; in degree $m+1$ the left side gives $a(m+1)-a(m)$ and the right side gives $(\Delta a)(m)=a(m+1)-a(m)$.
\end{proof}

Lemma~\ref{lem:key} is the whole engine: multiplication by $1-X$ on series is differencing on coefficients, up to a shift and a constant.

\begin{proposition}[Forward direction]\label{prop:fwd}
If $\Delta^ka$ is eventually zero then $(1-X)^k\operatorname{gen}(a)$ is a polynomial.
\end{proposition}

\begin{proof}
Induction on $k$; $k=0$ is Lemma~\ref{lem:evz}. For the step, choose $Q$ with $(1-X)^k\operatorname{gen}(\Delta a)=Q$ by induction, and compute
\[
  (1-X)^{k+1}\operatorname{gen}(a)=(1-X)^k\bigl[X\operatorname{gen}(\Delta a)+a(0)\bigr]=XQ+(1-X)^ka(0). \qedhere
\]
\end{proof}

\begin{lemma}\label{lem:divX}
If $X\varphi$ is a polynomial then so is $\varphi$.
\end{lemma}

\begin{proof}
The $n$-th coefficient of $\varphi$ is the $(n+1)$-st of $X\varphi$, hence vanishes for large $n$; apply Lemma~\ref{lem:evz}.
\end{proof}

\begin{proposition}[Converse]\label{prop:conv}
If $(1-X)^k\operatorname{gen}(a)=P$ is a polynomial then $\Delta^ka$ is eventually zero.
\end{proposition}

\begin{proof}
Induction on $k$, base Lemma~\ref{lem:evz}. For the step, Lemma~\ref{lem:key} gives
\[
  P=(1-X)^{k}\bigl[X\operatorname{gen}(\Delta a)+a(0)\bigr]
   = X\bigl[(1-X)^{k}\operatorname{gen}(\Delta a)\bigr]+(1-X)^{k}a(0),
\]
so $X\cdot\bigl[(1-X)^k\operatorname{gen}(\Delta a)\bigr]$ is a polynomial; by Lemma~\ref{lem:divX} so is $(1-X)^k\operatorname{gen}(\Delta a)$, and the inductive hypothesis applies to $\Delta a$.
\end{proof}

\begin{theorem}[Rationality criterion]\label{thm:crit}
For all $k$ and $a$: there is $P\in\QQ[q]$ with $(1-q)^k\operatorname{gen}(a)=P$ if and only if $\Delta^ka$ is eventually zero.
\end{theorem}

\begin{remark}
Since $(1-X)^k$ has constant term $1$, it is a unit of $\QQ[[q]]$, so $(1-X)^kf=P$ may always be rewritten $f=P\cdot((1-X)^k)^{-1}$. Nothing is lost by the multiplicative phrasing.
\end{remark}

\section{Polynomial growth and the binomial generating function}

\begin{definition}
For $p\in\QQ[x]$ set $(\delta p)(x)=p(x+1)-p(x)$, the \emph{discrete derivative}.
\end{definition}

\begin{lemma}\label{lem:degdrop}
If $\deg p\le d+1$ then $\deg(\delta p)\le d$.
\end{lemma}

\begin{proof}
Constants are killed. Otherwise $p(x+1)$ has the same degree and leading coefficient as $p$ (composition with the monic linear $x+1$ preserves both), so the leading terms cancel and the degree drops strictly.
\end{proof}

Since $a(n)=p(n)$ implies $(\Delta a)(n)=(\delta p)(n)$, iterating gives:

\begin{proposition}\label{prop:kills}
If $\deg p\le d$ then $\Delta^{d+1}(n\mapsto p(n))\equiv0$.
\end{proposition}

Iterated differences depend only on the tail of a sequence (immediate induction), whence:

\begin{theorem}[Eventually polynomial $\Rightarrow$ denominator $(1-q)^{r+1}$]\label{thm:growth}
If $\deg p\le r$ and $a(n)=p(n)$ for all $n\ge N$, then $(1-q)^{r+1}\operatorname{gen}(a)$ is a polynomial.
\end{theorem}

\begin{lemma}[Pascal as a difference equation]\label{lem:pascal}
For $c_r(n)=\binom{n}{r}$ one has $\Delta c_{r+1}=c_r$, hence $\Delta^kc_{r+k}=c_r$.
\end{lemma}

\begin{theorem}[Binomial generating function]\label{thm:binom}
For every $r\ge0$,
\[
  (1-q)^{r+1}\sum_{n\ge0}\binom{n}{r}q^n=q^r,
  \qquad\text{i.e.}\qquad
  \sum_{n\ge0}\binom{n}{r}q^n=\frac{q^r}{(1-q)^{r+1}}.
\]
\end{theorem}

\begin{proof}
Induction on $r$. For $r=0$: $c_0\equiv1$, so $\Delta c_0=0$ and Lemma~\ref{lem:key} gives $(1-q)\operatorname{gen}(c_0)=1=q^0$. For the step,
\[
  (1-q)^{r+2}\operatorname{gen}(c_{r+1})
  =(1-q)^{r+1}\bigl[q\operatorname{gen}(\Delta c_{r+1})+c_{r+1}(0)\bigr]
  =q\,(1-q)^{r+1}\operatorname{gen}(c_r)=q\cdot q^r,
\]
using $c_{r+1}(0)=\binom{0}{r+1}=0$, Lemma~\ref{lem:pascal}, and the inductive hypothesis.
\end{proof}

\begin{theorem}[Optimality]\label{thm:binomsharp}
There is no polynomial $P$ with $(1-q)^r\sum_n\binom{n}{r}q^n=P(q)$.
\end{theorem}

\begin{proof}
Such a $P$ would force $\Delta^rc_r$ eventually zero by Theorem~\ref{thm:crit}; but $\Delta^rc_r=c_0\equiv1$ by Lemma~\ref{lem:pascal}.
\end{proof}

\section{Newton's formula and the complete classification}

\begin{definition}
The \emph{shifted binomial functions} are $b_{N,j}(n)=\binom{n-N}{j}$, used only for $n\ge N$.
\end{definition}

\begin{lemma}\label{lem:shiftbinom}
For $n\ge N$, $(\Delta b_{N,j+1})(n)=b_{N,j}(n)$; consequently $\Delta^kb_{N,j}(n)=0$ for all $n\ge N$ whenever $j<k$.
\end{lemma}

\begin{lemma}[Hockey stick]\label{lem:hockey}
$\sum_{i<m}\binom{i}{j}=\binom{m}{j+1}$.
\end{lemma}

\begin{theorem}[Newton's forward difference formula]\label{thm:newton}
If $\Delta^ka$ vanishes for all $n\ge N$, then for all $n\ge N$
\[
  a(n)=\sum_{j=0}^{k-1}(\Delta^ja)(N)\binom{n-N}{j}.
\]
\end{theorem}

\begin{proof}
Translate so that $N=0$ and prove: $\Delta^kb\equiv0$ implies $b(m)=\sum_{j<k}(\Delta^jb)(0)\binom{m}{j}$. Induct on $k$; $k=0$ says $b\equiv0$. For the step apply the inductive hypothesis to $\Delta b$, giving $(\Delta b)(i)=\sum_{j<k}(\Delta^{j+1}b)(0)\binom{i}{j}$, and telescope:
\[
  b(m)-b(0)=\sum_{i<m}(\Delta b)(i)
  =\sum_{j<k}(\Delta^{j+1}b)(0)\sum_{i<m}\binom{i}{j}
  =\sum_{j<k}(\Delta^{j+1}b)(0)\binom{m}{j+1},
\]
by Lemma~\ref{lem:hockey}; re-indexing and adding $b(0)\binom{m}{0}$ gives the claim.
\end{proof}

\begin{theorem}[Three-way classification]\label{thm:tfae}
For $a:\NN\to\QQ$ and $k\ge0$ the following are equivalent: (1) $(1-q)^k\operatorname{gen}(a)$ is a polynomial; (2) $\Delta^ka$ is eventually zero; (3) there are $N$ and $d_0,\dots,d_{k-1}$ with $a(n)=\sum_{j<k}d_jb_{N,j}(n)$ for all $n\ge N$.
\end{theorem}

\begin{proof}
(1)$\Leftrightarrow$(2) is Theorem~\ref{thm:crit}; (2)$\Rightarrow$(3) is Theorem~\ref{thm:newton} with $d_j=(\Delta^ja)(N)$; (3)$\Rightarrow$(2) by linearity of $\Delta^k$, Lemma~\ref{lem:shiftbinom}, and tail-invariance of iterated differences.
\end{proof}

The function $b_{N,j}$ is realised by the honest polynomial
\[
  \beta_{N,j}(x)=\frac{1}{j!}(x-N)(x-N-1)\cdots(x-N-j+1),
\]
of degree exactly $j$, since the falling factorial at the nonnegative integer $n-N$ equals $j!\binom{n-N}{j}$. Hence:

\begin{theorem}[Polynomial classification]\label{thm:polyclass}
For $a:\NN\to\QQ$ and $r\ge0$, there exists $P$ with $(1-q)^{r+1}\operatorname{gen}(a)=P$ if and only if there exist $N$ and $p\in\QQ[x]$ with $\deg p\le r$ and $a(n)=p(n)$ for all $n\ge N$.
\end{theorem}

\begin{proof}
($\Leftarrow$) Theorem~\ref{thm:growth}. ($\Rightarrow$) By Theorem~\ref{thm:crit}, $\Delta^{r+1}a$ vanishes from some $N$; by Theorem~\ref{thm:newton}, $a(n)=\sum_{j\le r}(\Delta^ja)(N)\binom{n-N}{j}$ for $n\ge N$, and $p=\sum_{j\le r}(\Delta^ja)(N)\beta_{N,j}$ is a polynomial of degree $\le r$ with these values.
\end{proof}

Thus the minimal exponent $k$ with $(1-q)^kH$ polynomial equals one plus the eventual polynomial degree of the coefficient sequence: the denominator is a measurement, not slack.

\section{Orbits of injective tuples, and the main theorem}

\begin{proposition}[Transitivity $=$ one orbit]\label{prop:oneorbit}
For a $G$-set $Y$ and $r\ge0$: $t_r(Y)=1$ if and only if $Y$ is $r$-transitive.
\end{proposition}

\begin{proof}
If the orbit set is a singleton it is nonempty, so $\Inj(r,Y)\ne\emptyset$, and any two injective $r$-tuples share a class, hence lie in a common orbit. Conversely transitivity makes the orbit space a subsingleton and nonemptiness makes it nonempty; a nonempty subsingleton is a singleton.
\end{proof}

\begin{proposition}\label{prop:empty}
If $\Inj(r,Y)=\emptyset$ then $t_r(Y)=0$.
\end{proposition}

\begin{proof}[Proof of Theorem~\ref{thm:A}]
Let $Y_n$ be $r$-transitive for $n\ge N$. By Proposition~\ref{prop:oneorbit}, $a(n)=t_r(Y_n)=1$ for $n\ge N$, so $(\Delta a)(n)=1-1=0$ for $n\ge N$, i.e.\ $\Delta^1a$ is eventually zero. Proposition~\ref{prop:fwd} with $k=1$ produces $P$ with $(1-q)H_r=P$; multiplying by $(1-q)^r$ gives $(1-q)^{r+1}H_r=(1-q)^rP$, again a polynomial.
\end{proof}

Note where the hypothesis is used: transitivity serves \emph{only} to pin the eventual value of the orbit count to the constant $1$.

\begin{proof}[Proof of Theorem~\ref{thm:B}]
We prove the general statement: if $a(n)=c$ for all $n\ge N$ and $(1-q)\operatorname{gen}(a)=P$, then $P(1)=c$. Comparing coefficients gives $P_0=a(0)$ and $P_{n+1}=a(n+1)-a(n)$. Choosing $m\ge\max(N,\deg P)$ and telescoping,
\[
  P(1)=\sum_{i=0}^{m}P_i=a(0)+\bigl(a(m)-a(0)\bigr)=a(m)=c.
\]
Apply with $c=1$, valid by Proposition~\ref{prop:oneorbit}.
\end{proof}

Since $(1-q)H_r=P$ with $P(1)=1$, the pole at $q=1$ is simple with residue $\lim_{q\to1}(q-1)H_r(q)=-1$.

\begin{proof}[Proof of Theorem~\ref{thm:C}]
Proposition~\ref{prop:empty} gives $t_r(Y_n)=0$ for $n<N$ and Proposition~\ref{prop:oneorbit} gives $t_r(Y_n)=1$ for $n\ge N$, so $a$ is the step sequence $[\,n\ge N\,]$, with $\operatorname{gen}(a)=q^N+q^{N+1}+\cdots=q^N/(1-q)$; equivalently $(1-q)\operatorname{gen}(a)=q^N$, checked coefficientwise.
\end{proof}

\begin{example}[Symmetric groups]\label{ex:sym}
Let $Y_n=\{1,\dots,n\}$ with $G_n=S_n$. For $n\ge r$ the action on injective $r$-tuples is transitive: given two lists of $r$ distinct labels, the induced bijection extends arbitrarily to the equinumerous complements. For $n<r$ pigeonhole forbids any injection $\{1,\dots,r\}\hookrightarrow\{1,\dots,n\}$. Theorem~\ref{thm:C} gives $H_r(q)=q^r/(1-q)$, with $P(q)=q^r$ and $P(1)=1$.
\end{example}

\section{Sharpness: the trivial group}

\begin{proposition}\label{prop:triv}
If $G$ acts trivially on $Y$ then every injective $r$-tuple is fixed by every $g$, so each orbit is a singleton and $t_r(Y)=\#\Inj(r,Y)$.
\end{proposition}

\begin{proposition}\label{prop:falling}
For $Y_n=\{1,\dots,n\}$ with the trivial group, $t_r(Y_n)=n^{\underline r}=n(n-1)\cdots(n-r+1)=r!\binom{n}{r}$.
\end{proposition}

\begin{proof}[Proof of Theorem~\ref{thm:D}]
By Proposition~\ref{prop:falling} the coefficient sequence is $r!\,c_r$; generating functions are $\QQ$-linear, so Theorem~\ref{thm:binom} gives $(1-q)^{r+1}H_r=r!\,q^r$. If $(1-q)^rH_r$ were a polynomial then, by Theorem~\ref{thm:crit} and linearity of $\Delta$, the sequence $r!\,\Delta^rc_r=r!\,c_0\equiv r!$ would be eventually zero, contradicting $r!\ne0$.
\end{proof}

\begin{corollary}[Transitivity collapses the denominator]
For the graded set $Y_n=\{1,\dots,n\}$ one has $(1-q)H_r^{S_\bullet}(q)=q^r$, while no polynomial $P$ satisfies $(1-q)^rH_r^{\mathrm{triv}}(q)=P(q)$. The pole order jumps from $1$ to $r+1$ purely by removing symmetry, with the grades unchanged.
\end{corollary}

\section{A transitivity-free route: Burnside's lemma}

\begin{theorem}[Burnside for injective tuples]\label{thm:burnside}
Let a finite group $G$ act on a finite set $Y$. Then
\[
  \sum_{g\in G}\bigl|\Fix_{\Inj(r,Y)}(g)\bigr| = t_r(Y)\cdot|G|.
\]
\end{theorem}

\begin{proof}
$\Inj(r,Y)$ is finite, being a subset of $Y^r$, and carries a $G$-action; apply the orbit-counting lemma to it.
\end{proof}

\begin{theorem}[Fixed-point growth criterion]\label{thm:fixgrowth}
Let a fixed finite group $G$ act on each grade $Y_n$ of a graded set, all $Y_n$ finite, and suppose there are $N$ and polynomials $p_g\in\QQ[x]$ with $\deg p_g\le r$ and $|\Fix_{\Inj(r,Y_n)}(g)|=p_g(n)$ for all $g\in G$ and $n\ge N$. Then $(1-q)^{r+1}H_r(q)$ is a polynomial.
\end{theorem}

\begin{proof}
Put $p=\frac{1}{|G|}\sum_{g}p_g$, of degree $\le r$. For $n\ge N$, Theorem~\ref{thm:burnside} gives $t_r(Y_n)|G|=\sum_gp_g(n)$, so $t_r(Y_n)=p(n)$; apply Theorem~\ref{thm:growth}.
\end{proof}

The criterion is non-vacuous: for a constant family $Y_n=Y$ with a single finite $G$, each fixed-point count is constant in $n$, hence a degree-$0$ polynomial. The two sufficient conditions --- eventual transitivity and polynomial fixed-point growth --- are logically independent: the first says the group is large relative to the tuple object, the second that each element's fixed locus is tame. Burnside's lemma is the bridge converting the second into a statement about the sequence $t_r(Y_\bullet)$.

\section{Structural closure and the transitivity profile}

\begin{definition}
Let $R_1=\bigl\{f\in\QQ[[q]] : \exists k,\ \exists P\in\QQ[q],\ (1-q)^kf=P\bigr\}$.
\end{definition}

\begin{theorem}\label{thm:subring}
$R_1$ is a subring of $\QQ[[q]]$ containing $\QQ[q]$.
\end{theorem}

\begin{proof}
Polynomials lie in $R_1$ with $k=0$. If $(1-q)^kf=P$ and $(1-q)^\ell g=Q$ then $(1-q)^{k+\ell}(f+g)=(1-q)^\ell P+(1-q)^kQ$ and $(1-q)^{k+\ell}(fg)=PQ$; and $(1-q)^k(-f)=-P$.
\end{proof}

\begin{proposition}
$\operatorname{gen}(a)\in R_1$ iff $\Delta^ka$ is eventually zero for some $k$, iff $a$ is eventually polynomial.
\end{proposition}

\begin{corollary}[Closure for Hilbert series]\label{cor:cauchy}
If $Y$ is eventually $r$-transitive and $Y'$ eventually $s$-transitive, with numerators $P,Q$, then
\[
  (1-q)^2\,H_r^{Y}(q)\,H_s^{Y'}(q)=P(q)\,Q(q),
\]
so the Cauchy product has a pole at $q=1$ of order at most $2$. Pole orders add, never more.
\end{corollary}

\begin{lemma}[Downward closure]\label{lem:down}
If $Y$ is $r$-transitive and $s\le r$, then $Y$ is $s$-transitive.
\end{lemma}

\begin{proof}
Restricting an injective $r$-tuple to its first $s$ coordinates gives an injective $s$-tuple, so $\Inj(s,Y)\ne\emptyset$. The existence of an injective $r$-tuple gives $|Y|\ge r$; hence any two injective $s$-tuples extend to injective $r$-tuples, which $r$-transitivity carries onto each other, and restricting the transporting element gives the required transitivity.
\end{proof}

\begin{theorem}[Rational profile]\label{thm:profile}
If the grades of $Y$ are eventually $r$-transitive, then for every $s\le r$ there is $P_s$ with $(1-q)H_s(q)=P_s(q)$ and $P_s(1)=1$; in particular each $H_s$ has denominator dividing $(1-q)^{s+1}$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:down} the grades are eventually $s$-transitive; apply Theorems~\ref{thm:A} and \ref{thm:B} at level $s$.
\end{proof}

\section{Algorithms}

\subsection{Difference-table rationality test}
Given a prefix $a_0,\dots,a_{M-1}$, a bound $k$ and a window $w$: build the difference table row by row (row $i+1$ is the forward difference of row $i$, one entry shorter) and test whether the last $w$ entries of row $k$ vanish. Cost $O(kM)$ additions. By Theorem~\ref{thm:polyclass} the minimal such $k$ is one more than the eventual polynomial degree.

\subsection{Numerator extraction}
Given $a$ and an exponent $k$ that clears it, the numerator coefficients are the convolution of $a$ with those of $(1-q)^k$:
\[
  P_m=\sum_{i=0}^{\min(m,k)}(-1)^i\binom{k}{i}a_{m-i}.
\]
Once $\Delta^ka$ vanishes from $N$ on, $P_m=0$ for $m>N+k-1$. Cost $O(kN)$. The check $\sum_mP_m=1$ validates Theorem~\ref{thm:B}.

\subsection{Newton reconstruction}
Read the entries $(\Delta^ja)(N)$, $j<k$, from the difference table's column at $N$; these are the Newton coefficients in $a(n)=\sum_{j<k}(\Delta^ja)(N)\binom{n-N}{j}$. Cost $O(kN)$ to build, $O(k)$ per evaluation, $O(k^2)$ to convert to the monomial basis via the $\beta_{N,j}$.

\section{Worked examples}

\begin{example}[Symmetric groups, $r=3$]
$t_3(Y_n)=0,0,0,1,1,1,\dots$; one difference suffices, the numerator is $q^3$, $P(1)=1$, and $H_3(q)=q^3/(1-q)=q^3+q^4+\cdots$.
\end{example}

\begin{example}[Trivial group, $r=3$]
$t_3(Y_n)=n(n-1)(n-2)=0,0,0,6,24,60,120,210,\dots$. The difference rows are $0,0,6,18,36,60,\dots$; $0,6,12,18,24,\dots$; $6,6,6,6,\dots$; $0,0,0,\dots$. Exactly four differences are needed, matching $k=r+1=4$; the constant $6=3!$ in row three certifies that $k=3$ fails. Numerator: $(1-q)^4H_3(q)=6q^3$.
\end{example}

\begin{example}[Mixed family]
If the grades are $r$-transitive from $N=5$ on with low orbit counts $0,3,2,7,4$, then $P(q)=3q-q^2+5q^3-3q^4-3q^5$ and $\sum_mP_m=1$, confirming Theorem~\ref{thm:B}. The defect region is recorded verbatim in the numerator.
\end{example}

\begin{example}[Eventually quadratic]
If $t_2(Y_n)=n^2-3n+4$ for $n\ge2$, then $k=3=r+1$ with $r=2$ suffices and no smaller $k$ does, since $\Delta^2$ of a genuine quadratic is the nonzero constant $2$.
\end{example}

\section{Discussion}

\paragraph{What the pole order measures.} The order of the pole of $H_r$ at $q=1$ is a symmetry invariant: by Theorem~\ref{thm:polyclass} it equals one plus the eventual polynomial degree of the orbit-counting sequence. Full $r$-transitivity forces degree $0$ and pole order $1$; total absence of symmetry gives degree $r$ and pole order $r+1$. Intermediate degrees measure a defect of transitivity.

\paragraph{The numerator as a record of the defect region.} The proof of Theorem~\ref{thm:B} shows the coefficients of $P$ to be $a_0$ and the successive differences $a_{n+1}-a_n$. Thus $P$ carries exactly the information of the finitely many grades before transitivity sets in, subject to the single global law $P(1)=1$. Theorem~\ref{thm:C} is the extreme case where the defect region is as empty as possible.

\paragraph{Relation to classical rationality theorems.} Denominators that are powers of $1-q$ and eventually polynomial coefficients are the signature of Hilbert--Serre type theorems in graded commutative algebra and of Ehrhart theory. The present results place orbit counts of graded group actions in the same family, with the difference operator in the structural role. All proofs are elementary and constructive: Pascal's rule, telescoping, and the invertibility of $1-q$ in $\QQ[[q]]$.

\paragraph{Limitations.} The theorems say nothing about how fast transitivity sets in; the threshold $N$ is an input, visible in the series only through the numerator's degree. Everything concerns the pole at $q=1$; transitivity along an arithmetic progression should instead produce poles at roots of unity. Finally, the graded product is treated only at the level of series (Corollary~\ref{cor:cauchy}); identifying the orbit count of a graded product with the convolution of the factors' counts requires a separate combinatorial argument.

\section{Future directions}

\begin{conjecture}[Orbit-counting rigidity]
Let $Y$ be $r$-transitive in every grade $n\ge N$ with no injective $r$-tuple in any grade $n<N$. Then the numerator $P$ with $(1-q)H=P$ equals $q^N$; conversely, if $P$ is a monomial then the transitivity threshold is $\deg P$ and the grades below carry no injective $r$-tuple. One direction is Theorem~\ref{thm:C}. The guiding insight is that the numerator is a \emph{complete invariant of the defect region}, with $P(1)=1$ the only global constraint.
\end{conjecture}

\begin{conjecture}[Quasi-polynomial grading]
If the grades are $r$-transitive only along an arithmetic progression $n\equiv a\pmod m$, and $t_r(Y_n)$ is eventually periodic modulo $m$, then $\sum_nt_r(Y_n)q^n$ is rational with denominator dividing $(1-q^m)^{r+1}$ and lies in the subring generated by $R_1$ and the $m$-th root-of-unity filters. Since $1-q^m=\prod_{\zeta^m=1}(1-\zeta q)$, periodic transitivity should trade the single pole at $q=1$ for a full orbit of poles at the $m$-th roots of unity, with $\Delta$ replaced by the $m$-step difference $a(n+m)-a(n)$. The engine uses only the identity $(1-q)\operatorname{gen}(a)=q\operatorname{gen}(\Delta a)+a(0)$, which holds verbatim in the $m$-step setting.
\end{conjecture}

\begin{conjecture}[Sub-additivity of pole order under products]
For graded $G$-sets $Y,Y'$ let $(Y\otimes Y')_n=\bigsqcup_{i+j=n}Y_i\times Y'_j$ as a graded $G\times G'$-set. If $Y$ is eventually $r$-transitive and $Y'$ eventually $s$-transitive, then $Y\otimes Y'$ is eventually $\min(r,s)$-transitive and its Hilbert series has a pole at $q=1$ of order at most $2$, with equality iff both factors have infinitely many nonempty grades. The series-level bound is Corollary~\ref{cor:cauchy}; what is open is that the Hilbert series of the product is the Cauchy product.
\end{conjecture}

\begin{conjecture}[Converse to the Burnside criterion]
If $(1-q)^{r+1}H_r$ is a polynomial for a family with a fixed finite group $G$, must each individual fixed-point count $n\mapsto|\Fix_{\Inj(r,Y_n)}(g)|$ be eventually polynomial of degree $\le r$, or can cancellation among group elements hide non-polynomial individual behaviour?
\end{conjecture}

\begin{conjecture}[Effective thresholds]
Bound the transitivity threshold $N$ in terms of $\deg P$. Theorem~\ref{thm:C} gives $N=\deg P$ in the extreme case; in general one expects $N\le\deg P$, the gap measured by sub-threshold grades that happen already to be transitive.
\end{conjecture}

\section{Conclusion}

For a graded $G$-set whose grades are eventually $r$-transitive, the generating function of the orbit counts of injective $r$-tuples is rational with denominator dividing $(1-q)^{r+1}$, and in fact the single factor $1-q$ suffices; the numerator evaluates to $1$ at $q=1$ and, in the clean case, is the monomial $q^N$ recording the transitivity threshold. Without transitivity the exponent $r+1$ is exactly right, as the trivial-group family with orbit count $r!\binom{n}{r}$ and generating function $r!\,q^r/(1-q)^{r+1}$ shows. Underlying all of it is a complete elementary classification: $(1-q)^k$ clears a generating function precisely when the $k$-th forward difference of its coefficients vanishes eventually, precisely when those coefficients are eventually a polynomial of degree less than $k$. The pole order at $q=1$ is a sharp numerical measure of how much symmetry a graded family of group actions carries.

