"""Burnside Orbit Counting on Injective r-Tuples.

Computes t_r(Y) = #(Inj(r,Y)/G) for a finite permutation group G acting on
{0,...,n-1}, in two independent ways:

  * union-find over the action graph on injective r-tuples, and
  * Burnside averaging, t_r(Y) = (1/|G|) * sum_{g in G} |Fix(g)|,

and assembles the resulting Hilbert series data across a range of grades.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import permutations
from typing import Callable, Dict, List, Sequence, Tuple

Perm = Tuple[int, ...]
Tup = Tuple[int, ...]


def symmetric_group(n: int) -> List[Perm]:
    return list(permutations(range(n)))


def cyclic_group(n: int) -> List[Perm]:
    return [tuple((i + s) % n for i in range(n)) for s in range(n)]


def dihedral_group(n: int) -> List[Perm]:
    rots = [tuple((i + s) % n for i in range(n)) for s in range(n)]
    refs = [tuple((s - i) % n for i in range(n)) for s in range(n)]
    return list(dict.fromkeys(rots + refs))


def trivial_group(n: int) -> List[Perm]:
    return [tuple(range(n))]


def injective_tuples(n: int, r: int) -> List[Tup]:
    return list(permutations(range(n), r))


def act(g: Perm, t: Tup) -> Tup:
    return tuple(g[x] for x in t)


def torbits_unionfind(group: Sequence[Perm], n: int, r: int) -> int:
    """Orbit count by union-find; cost O(|G| * n^{underline r} * alpha)."""
    tuples = injective_tuples(n, r)
    index: Dict[Tup, int] = {t: i for i, t in enumerate(tuples)}
    parent = list(range(len(tuples)))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for t in tuples:
        for g in group:
            a, b = find(index[t]), find(index[act(g, t)])
            if a != b:
                parent[a] = b
    return len({find(i) for i in range(len(tuples))})


def torbits_burnside(group: Sequence[Perm], n: int, r: int) -> Fraction:
    """Orbit count by Burnside averaging; cost O(|G| * n^{underline r})."""
    tuples = injective_tuples(n, r)
    total = sum(sum(1 for t in tuples if act(g, t) == t) for g in group)
    return Fraction(total, len(group))


def hilbert_prefix(group_of: Callable[[int], List[Perm]], r: int,
                   nmax: int) -> List[Fraction]:
    """The first nmax+1 coefficients of the transitivity Hilbert series."""
    return [torbits_burnside(group_of(n), n, r) if n > 0 else
            (Fraction(1) if r == 0 else Fraction(0)) for n in range(nmax + 1)]


if __name__ == "__main__":
    for name, mk in (("S_n", symmetric_group), ("C_n", cyclic_group),
                     ("D_n", dihedral_group), ("1", trivial_group)):
        for r in (1, 2):
            row = []
            for n in range(1, 7):
                u = torbits_unionfind(mk(n), n, r)
                b = torbits_burnside(mk(n), n, r)
                assert Fraction(u) == b, (name, n, r, u, b)
                row.append(u)
            print(f"{name:>4}  r={r}:  t_r(Y_n) for n=1..6 = {row}")
